  const panels=this.panels(a,p),sections=p?[['care','Care'],['stats','Stats'],['water-schedule','Water Schedule'],['notifications','Notifications']]:[['care','Map'],['plants','Plants'],['water-schedule','Water schedule'],['stats','Stats'],['notifications','Notifications']];
  this.section??='care';
  const tabs='<nav class="tabs" aria-label="Plant sections">'+sections.map(([key,label])=>`<button data-section="${key}" aria-pressed="${this.section===key}">${label}</button>`).join('')+'</nav>';
  this.shadowRoot.innerHTML=`<style>${css}${extra}${window.MungoonPlantMapCSS||''}.ha-detail .hub-home{position:static;margin-bottom:8px}.photo{border:4px solid var(--water-ring,#ed6664);box-sizing:border-box}</style><ha-card class="${p?'ha-detail':'ha-home'}" data-section="${this.section}"><button class="hub-home" id="hub-home">⌂ Home</button>${p?'':`<div class="ha-title"><h1>Plants at home</h1><p>${a.plants.length} plants · Friday round 13:30 Dubai</p></div>`}${p?tabs:''}<div id="care">${content}</div>${panels}${p?'':tabs}</ha-card>`;
  this.shadowRoot.querySelector('#hub-home').onclick=()=>this._hass.callService('cast','show_lovelace_view',{entity_id:'media_player.hub',dashboard_path:'nest-hub',view_path:'home'});
  const selectSection=name=>{this.section=name;this.shadowRoot.querySelector('ha-card').dataset.section=name;this.shadowRoot.querySelectorAll('[data-section]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.section===name));});for(const key of ['care','stats','water-schedule','notifications'])this.shadowRoot.getElementById(key).hidden=key!==name&&!(key==='care'&&name==='plants');this.mapController?.draw();};
  this.shadowRoot.querySelectorAll('button[data-section]').forEach(b=>b.onclick=()=>selectSection(b.dataset.section));selectSection(this.section);
  if(!p){this.mapController?.bind();return;}
